import { neonColors } from "../constants/color";
import { CSSProperties } from "react";
import { IoCloseCircle } from "react-icons/io5";

const CreateEditCard = () => {
  const color = neonColors[0];
  //   const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
  //     useSortable({ id});

  const style: CSSProperties = {
    padding: 8,
    marginBottom: 8,
    borderWidth: 2,
    color: color,
    borderStyle: "solid",
    borderColor: color,
    borderRadius: 10,
    display: "flex",
    flexDirection: "row",
    alignItems:'center',
    justifyContent:'space-between',
  };
  const textInput = () => {
    return (
      <input
        style={{
          backgroundColor: "transparent",
          marginBottom: 2,
          borderWidth: 0,
          borderStyle: "solid",
          borderBottomWidth:1,
          display:'flex'
        }}
      />
    );
  };
  return (
    <div style={style}>
      <div style={{display:'flex',flex: 9,flexDirection:'column'}}>
      {textInput()}
      {textInput()}
      </div>
      <div style={{display:'flex',flex:1,backgroundColor:'red'}}><IoCloseCircle /></div>
    </div>
  );
};

export default CreateEditCard;
